// Extract verse from webhook payload or use default
const verse = $input.item.json.verse || 'Salmos 23:1';
const maxRetries = $input.item.json.maxRetries || 3;

return {
  verse,
  maxRetries,
  timestamp: new Date().toISOString(),
  sessionId: `session-${Date.now()}`
};

// Read image metadata
const fs = require('fs');
const path = require('path');

const verse = $json.verse;
const verseSlug = verse.replace(/\s+/g, '-').replace(/:/g, '-');
const metadataPath = `/home/suario/ruy-projects/project-yt/output/image-metadata/images-completed-${verseSlug}-*.json`;

// Find the file
const files = fs.readdirSync('/home/suario/ruy-projects/project-yt/output/image-metadata/')
  .filter(f => f.includes(verseSlug) && f.startsWith('images-completed'));

if (files.length === 0) {
  throw new Error('No image metadata found');
}

const metadata = JSON.parse(
  fs.readFileSync(`/home/suario/ruy-projects/project-yt/output/image-metadata/${files[0]}`, 'utf-8')
);

return {
  verse,
  imageCount: metadata.images.length,
  images: metadata.images
};

// Call Agent 5 for each image to generate video
const verse = $json.verse;
const images = $json.images;

const { execSync } = require('child_process');
const fs = require('fs');
const path = require('path');

const verseSlug = verse.replace(/\s+/g, '-').replace(/:/g, '-');

// Ejecutar Agent 5 con batch de imágenes
const command = `cd /home/suario/ruy-projects/project-yt && node agents/agent-5-video-animator.js "${verse}"`;

try {
  execSync(command, { stdio: 'inherit' });

  // Read video metadata
  const videoFiles = fs.readdirSync('/home/suario/ruy-projects/project-yt/output/video-metadata/')
    .filter(f => f.includes(verseSlug) && f.startsWith('video-metadata'));

  if (videoFiles.length === 0) {
    throw new Error('No video metadata found');
  }

  const videoMetadata = JSON.parse(
    fs.readFileSync(`/home/suario/ruy-projects/project-yt/output/video-metadata/${videoFiles[0]}`, 'utf-8')
  );

  return {
    verse,
    videoCount: videoMetadata.clips?.length || 0,
    videoMetadata
  };

} catch (error) {
  throw new Error(`Agent 5 failed: ${error.message}`);
}

// Generate audio with Agent 6
const verse = $json.verse;
const { execSync } = require('child_process');
const fs = require('fs');

const verseSlug = verse.replace(/\s+/g, '-').replace(/:/g, '-');

// Ejecutar Agent 6 (audio TTS)
const command = `cd /home/suario/ruy-projects/project-yt && bash agents/run-agent-6.sh "${verse}"`;

try {
  execSync(command, { stdio: 'inherit' });

  // Read audio metadata
  const audioFiles = fs.readdirSync('/home/suario/ruy-projects/project-yt/output/audio-metadata/')
    .filter(f => f.includes(verseSlug));

  if (audioFiles.length === 0) {
    throw new Error('No audio metadata found');
  }

  const audioMetadata = JSON.parse(
    fs.readFileSync(`/home/suario/ruy-projects/project-yt/output/audio-metadata/${audioFiles[0]}`, 'utf-8')
  );

  return {
    verse,
    audioMetadata
  };

} catch (error) {
  throw new Error(`Agent 6 failed: ${error.message}`);
}

// Continue Agent 9 - Generate base image with Magnific
const verse = $json.verse;
const fs = require('fs');
const path = require('path');

const verseSlug = verse.replace(/\s+/g, '-').replace(/:/g, '-');

// Read prompt file generated by Agent 9
const promptPath = `/home/suario/ruy-projects/project-yt/output/thumbnails/prompt-base-${verseSlug}.txt`;

if (!fs.existsSync(promptPath)) {
  throw new Error('Agent 9 prompt file not found');
}

const basePrompt = fs.readFileSync(promptPath, 'utf-8');

return {
  verse,
  magnificParams: {
    prompt: basePrompt,
    mode: 'recraft-v4-1',
    aspectRatio: '16:9',
    count: 1
  }
};

// Wait for creation completion
const creationIdentifier = $json.identifier || $json.creationIdentifier;

if (!creationIdentifier) {
  throw new Error('No creation identifier returned from Magnific');
}

const { execSync } = require('child_process');

// Poll for completion (max 2 minutes)
let completed = false;
let attempts = 0;
const maxAttempts = 24; // 24 * 5s = 2 minutes

while (!completed && attempts < maxAttempts) {
  try {
    // Check status via Magnific API or file system
    const result = execSync(
      `curl -s "${process.env.MAGNIFIC_API_URL}/creations/${creationIdentifier}"`,
      { encoding: 'utf-8' }
    );

    const status = JSON.parse(result);

    if (status.status === 'completed') {
      completed = true;
      return {
        verse: $json.verse,
        creationIdentifier,
        imageUrl: status.url,
        status: 'completed'
      };
    }

    if (status.status === 'failed') {
      throw new Error('Magnific generation failed');
    }

    // Wait 5 seconds before next check
    execSync('sleep 5');
    attempts++;

  } catch (error) {
    throw new Error(`Error checking Magnific status: ${error.message}`);
  }
}

if (!completed) {
  throw new Error('Timeout waiting for Magnific generation');
}

// Continue Agent 9 - Compose text overlay
const verse = $json.verse;
const baseImageUrl = $json.imageUrl;

const { execSync } = require('child_process');
const fs = require('fs');
const https = require('https');
const path = require('path');

const verseSlug = verse.replace(/\s+/g, '-').replace(/:/g, '-');
const baseImagePath = `/home/suario/ruy-projects/project-yt/output/thumbnails/base-${verseSlug}.png`;

// Download base image
const file = fs.createWriteStream(baseImagePath);

await new Promise((resolve, reject) => {
  https.get(baseImageUrl, (response) => {
    response.pipe(file);
    file.on('finish', () => {
      file.close();
      resolve();
    });
  }).on('error', reject);
});

// Compose with text
try {
  execSync(`cd /home/suario/ruy-projects/project-yt && node compose-thumbnail.js "${verse}"`, {
    stdio: 'inherit'
  });

  const thumbnailPath = `/home/suario/ruy-projects/project-yt/output/thumbnails/thumbnail-${verseSlug}.png`;

  if (!fs.existsSync(thumbnailPath)) {
    throw new Error('Thumbnail composition failed');
  }

  return {
    verse,
    thumbnailPath,
    status: 'completed'
  };

} catch (error) {
  throw new Error(`Thumbnail composition failed: ${error.message}`);
}

// Upload to YouTube
const verse = $json.verse;
const { execSync } = require('child_process');
const fs = require('fs');

const verseSlug = verse.replace(/\s+/g, '-').replace(/:/g, '-');

// Paths
const videoPath = `/home/suario/ruy-projects/project-yt/output/final-videos/final-${verseSlug}.mp4`;
const thumbnailPath = `/home/suario/ruy-projects/project-yt/output/thumbnails/thumbnail-${verseSlug}.png`;
const metadataPath = `/home/suario/ruy-projects/project-yt/output/youtube-metadata/youtube-metadata-${verseSlug}.json`;

// Verify files exist
if (!fs.existsSync(videoPath)) {
  throw new Error(`Video not found: ${videoPath}`);
}

if (!fs.existsSync(thumbnailPath)) {
  throw new Error(`Thumbnail not found: ${thumbnailPath}`);
}

if (!fs.existsSync(metadataPath)) {
  throw new Error(`Metadata not found: ${metadataPath}`);
}

const metadata = JSON.parse(fs.readFileSync(metadataPath, 'utf-8'));

// Upload video
try {
  const uploadCommand = `cd /home/suario/ruy-projects/project-yt && node upload-video.js "${verse}"`;
  const result = execSync(uploadCommand, { encoding: 'utf-8' });

  // Extract video ID from output
  const videoIdMatch = result.match(/Video ID: ([a-zA-Z0-9_-]+)/);
  const videoId = videoIdMatch ? videoIdMatch[1] : null;

  if (!videoId) {
    throw new Error('Failed to extract video ID from upload result');
  }

  return {
    verse,
    videoId,
    videoUrl: `https://www.youtube.com/watch?v=${videoId}`,
    title: metadata.youtube.title,
    uploadedAt: new Date().toISOString()
  };

} catch (error) {
  throw new Error(`YouTube upload failed: ${error.message}`);
}

// Success notification
const verse = $json.verse;
const videoUrl = $json.videoUrl;
const title = $json.title;

const message = `✅ VIDEO PUBLICADO EXITOSAMENTE\n\n📖 Versículo: ${verse}\n📺 URL: ${videoUrl}\n📝 Título: ${title}\n⏰ Publicado: ${new Date().toISOString()}`;

console.log(message);

return {
  success: true,
  verse,
  videoUrl,
  title,
  message
};

// Error handler
const error = $json.error || 'Unknown error';
const verse = $json.verse || 'Unknown verse';
const failedStep = $json.failedStep || 'Unknown step';

const message = `❌ PIPELINE FAILED\n\n📖 Versículo: ${verse}\n🚫 Error: ${error}\n📍 Paso fallido: ${failedStep}\n⏰ Timestamp: ${new Date().toISOString()}`;

console.error(message);

return {
  success: false,
  verse,
  error,
  failedStep,
  message
};
